1	// One-off scoring pass: combines local provider pricing + Artificial Analysis benchmark
2	// data into per-category recommendations. Run with: node scripts/compute-scores.ts
3	
4	import { readFile, writeFile, mkdir } from "node:fs/promises";
5	import path from "node:path";
6	
7	type Provider = "copilot" | "opencode-go";
8	
9	interface Candidate {
10	  provider: Provider;
11	  model: string;
12	  priceInput: number;
13	  priceOutput: number;
14	}
15	
16	interface MappingEntry {
17	  provider: Provider;
18	  providerModel: string;
19	  aaSlug: string | null;
20	}
21	
22	interface AaModel {
23	  id: string;
24	  name: string;
25	  slug: string;
26	  evaluations: {
27	    artificial_analysis_intelligence_index?: number | null;
28	    artificial_analysis_coding_index?: number | null;
29	    artificial_analysis_agentic_index?: number | null;
30	  };
31	  performance?: {
32	    median_output_tokens_per_second?: number | null;
33	  };
34	}
35	
36	interface CategoryWeights {
37	  agenticIndex?: number;
38	  codingIndex?: number;
39	  intelligenceIndex?: number;
40	  costEfficiency?: number;
41	  speed?: number;
42	}
43	
44	interface ScoredCandidate {
45	  provider: Provider;
46	  model: string;
47	  aaSlug: string;
48	  score: number;
49	  breakdown: Record<string, number>;
50	  priceBlendedPer1M: number;
51	}
52	
53	const OUTPUT_OUTPUT_TO_INPUT_RATIO = 3; // assume 3 output tokens per 1 input token (typical agentic workload)
54	
55	function blendedPrice(priceInput: number, priceOutput: number): number {
56	  const totalParts = 1 + OUTPUT_OUTPUT_TO_INPUT_RATIO;
57	  return (priceInput * 1 + priceOutput * OUTPUT_OUTPUT_TO_INPUT_RATIO) / totalParts;
58	}
59	
60	// Strips variant qualifiers like " (<= 256K tokens)", " (Off-Peak)", " (Peak)" so
61	// tiered/peak pricing rows collapse to one representative candidate per base model.
62	function baseModelName(model: string): string {
63	  let stripped = model;
64	  while (/\s*\([^)]*\)\s*$/.test(stripped)) {
65	    stripped = stripped.replace(/\s*\([^)]*\)\s*$/, "").trim();
66	  }
67	  return stripped;
68	}
69	
70	function dedupeCheapest(rows: { model: string; priceInput: number; priceOutput: number }[]): { model: string; priceInput: number; priceOutput: number }[] {
71	  const byBase = new Map<string, { model: string; priceInput: number; priceOutput: number }>();
72	  for (const row of rows) {
73	    const base = baseModelName(row.model);
74	    const existing = byBase.get(base);
75	    if (!existing || blendedPrice(row.priceInput, row.priceOutput) < blendedPrice(existing.priceInput, existing.priceOutput)) {
76	      byBase.set(base, { model: base, priceInput: row.priceInput, priceOutput: row.priceOutput });
77	    }
78	  }
79	  return [...byBase.values()];
80	}
81	
82	async function loadCandidates(): Promise<Candidate[]> {
83	  const copilotRaw = JSON.parse(await readFile(path.join("data", "copilot", "models-pricing.json"), "utf8"));
84	  const opencodeRaw = JSON.parse(await readFile(path.join("data", "opencode-go", "models-pricing.json"), "utf8"));
85	
86	  const copilotRows = dedupeCheapest(
87	    copilotRaw.models.map((m: { model: string; price1mInput: number; price1mOutput: number }) => ({
88	      model: m.model,
89	      priceInput: m.price1mInput,
90	      priceOutput: m.price1mOutput,
91	    })),
92	  );
93	  const opencodeRows = dedupeCheapest(
94	    opencodeRaw.models.map((m: { model: string; priceInput: number; priceOutput: number }) => ({
95	      model: m.model,
96	      priceInput: m.priceInput,
97	      priceOutput: m.priceOutput,
98	    })),
99	  );
100	
101	  return [
102	    ...copilotRows.map((r) => ({ provider: "copilot" as const, model: r.model, priceInput: r.priceInput, priceOutput: r.priceOutput })),
103	    ...opencodeRows.map((r) => ({ provider: "opencode-go" as const, model: r.model, priceInput: r.priceInput, priceOutput: r.priceOutput })),
104	  ];
105	}
106	
107	function normalize(value: number, min: number, max: number): number {
108	  if (max === min) return 1;
109	  return (value - min) / (max - min);
110	}
111	
112	async function main() {
113	  const config = JSON.parse(await readFile(path.join("config", "categories.json"), "utf8"));
114	  const candidates = await loadCandidates();
115	  const mapping: MappingEntry[] = JSON.parse(await readFile(path.join("data", "model-mapping.json"), "utf8"));
116	  const aaData = JSON.parse(await readFile(path.join("data", "artificial-analysis", "language-models.json"), "utf8"));
117	  const aaBySlug = new Map<string, AaModel>((aaData.models as AaModel[]).map((m) => [m.slug, m]));
118	
119	  const enriched: {
120	    provider: Provider;
121	    model: string;
122	    aaSlug: string;
123	    agenticIndex: number;
124	    codingIndex: number;
125	    intelligenceIndex: number;
126	    speed: number;
127	    blendedPrice1m: number;
128	  }[] = [];
129	
130	  for (const candidate of candidates) {
131	    const map = mapping.find((m) => m.provider === candidate.provider && m.providerModel === candidate.model);
132	    if (!map || !map.aaSlug) {
133	      console.warn(`Skipping ${candidate.provider}/${candidate.model}: no Artificial Analysis mapping.`);
134	      continue;
135	    }
136	    const aa = aaBySlug.get(map.aaSlug);
137	    if (!aa) {
138	      console.warn(`Skipping ${candidate.provider}/${candidate.model}: aaSlug "${map.aaSlug}" not found in fetched data.`);
139	      continue;
140	    }
141	    const { artificial_analysis_agentic_index, artificial_analysis_coding_index, artificial_analysis_intelligence_index } = aa.evaluations;
142	    const speed = aa.performance?.median_output_tokens_per_second;
143	    if (
144	      artificial_analysis_agentic_index == null ||
145	      artificial_analysis_coding_index == null ||
146	      artificial_analysis_intelligence_index == null ||
147	      speed == null
148	    ) {
149	      console.warn(`Skipping ${candidate.provider}/${candidate.model}: incomplete benchmark data for "${map.aaSlug}".`);
150	      continue;
151	    }
152	
153	    enriched.push({
154	      provider: candidate.provider,
155	      model: candidate.model,
156	      aaSlug: map.aaSlug,
157	      agenticIndex: artificial_analysis_agentic_index,
158	      codingIndex: artificial_analysis_coding_index,
159	      intelligenceIndex: artificial_analysis_intelligence_index,
160	      speed,
161	      blendedPrice1m: blendedPrice(candidate.priceInput, candidate.priceOutput),
162	    });
163	  }
164	
165	  const categories: Record<string, ScoredCandidate[]> = {};
166	
167	  for (const [categoryName, categoryConfig] of Object.entries(config.categories) as [string, { weights: CategoryWeights }][]) {
168	    const weights = categoryConfig.weights;
169	    if (enriched.length === 0) {
170	      categories[categoryName] = [];
171	      continue;
172	    }
173	
174	    const costEfficiencies = enriched.map((e) => 1 / e.blendedPrice1m);
175	    const ranges = {
176	      agenticIndex: [Math.min(...enriched.map((e) => e.agenticIndex)), Math.max(...enriched.map((e) => e.agenticIndex))],
177	      codingIndex: [Math.min(...enriched.map((e) => e.codingIndex)), Math.max(...enriched.map((e) => e.codingIndex))],
178	      intelligenceIndex: [Math.min(...enriched.map((e) => e.intelligenceIndex)), Math.max(...enriched.map((e) => e.intelligenceIndex))],
179	      speed: [Math.min(...enriched.map((e) => e.speed)), Math.max(...enriched.map((e) => e.speed))],
180	      costEfficiency: [Math.min(...costEfficiencies), Math.max(...costEfficiencies)],
181	    };
182	
183	    const scored: ScoredCandidate[] = enriched.map((e, i) => {
184	      const normAgentic = normalize(e.agenticIndex, ranges.agenticIndex[0], ranges.agenticIndex[1]);
185	      const normCoding = normalize(e.codingIndex, ranges.codingIndex[0], ranges.codingIndex[1]);
186	      const normIntelligence = normalize(e.intelligenceIndex, ranges.intelligenceIndex[0], ranges.intelligenceIndex[1]);
187	      const normSpeed = normalize(e.speed, ranges.speed[0], ranges.speed[1]);
188	      const normCost = normalize(costEfficiencies[i], ranges.costEfficiency[0], ranges.costEfficiency[1]);
189	
190	      const score =
191	        (weights.agenticIndex ?? 0) * normAgentic +
192	        (weights.codingIndex ?? 0) * normCoding +
193	        (weights.intelligenceIndex ?? 0) * normIntelligence +
194	        (weights.costEfficiency ?? 0) * normCost +
195	        (weights.speed ?? 0) * normSpeed;
196	
197	      return {
198	        provider: e.provider,
199	        model: e.model,
200	        aaSlug: e.aaSlug,
201	        score: Math.round(score * 1000) / 1000,
202	        breakdown: {
203	          agenticIndex: e.agenticIndex,
204	          codingIndex: e.codingIndex,
205	          intelligenceIndex: e.intelligenceIndex,
206	          speed: e.speed,
207	          costEfficiency: Math.round(costEfficiencies[i] * 1000) / 1000,
208	        },
209	        priceBlendedPer1M: Math.round(e.blendedPrice1m * 1000) / 1000,
210	      };
211	    });
212	
213	    scored.sort((a, b) => b.score - a.score);
214	    categories[categoryName] = scored.slice(0, config.topN);
215	  }
216	
217	  const outFile = path.join("data", "recommendations.json");
218	  await mkdir(path.dirname(outFile), { recursive: true });
219	  await writeFile(
220	    outFile,
221	    JSON.stringify(
222	      {
223	        generatedAt: new Date().toISOString(),
224	        topN: config.topN,
225	        candidatesConsidered: enriched.length,
226	        categories,
227	      },
228	      null,
229	      2,
230	    ),
231	  );
232	
233	  console.log(`Wrote recommendations for ${Object.keys(categories).length} categories (${enriched.length} scored candidates) to ${outFile}`);
234	}
235	
236	main().catch((err) => {
237	  console.error(err);
238	  process.exit(1);
239	});
